#!/bin/sh
# Assemble mkl_emu.c from the verified parts and build libmkl_emu.so
cd "$(dirname "$0")"
{
  printf '%s\n' "/* mkl_emu.c: bit-exact emulation of the MKL DGEMM('T','N') / DTRSM('L','U','T','U') calls of Gurobi 13.0.3's barrier" \
    "   (MKL statically linked in libgurobi130.so, AVX2 code path, alpha = beta = 1)." \
    "   Build: gcc -O2 -ffp-contract=off (only explicit fma() is fused). Generated by build_emu.sh from part_*.c. */" \
    "#include <math.h>"
  for p in part_gemv.c part_nocopy.c part_packed.c part_trsmv1.c part_trsmbig.c emu_dispatch.c; do
    printf '\n/* ======== %s ======== */\n' "$p"; grep -v '^#include <math.h>' "$p"
  done
} > mkl_emu.c
gcc -O2 -ffp-contract=off -Wall -shared -fPIC -o libmkl_emu.so mkl_emu.c -lm
